// Low-resolution Canvas 3D fallback sharing the exact game scene and camera.
import * as T from './vendor/three.module.js';
export class SoftwareRenderer{
 constructor(canvas){this.domElement=canvas;this.ctx=canvas.getContext('2d',{alpha:false});if(!this.ctx)throw new Error('Canvas is unavailable.');this.shadowMap={enabled:false};this.info={render:{calls:0}};this.isSoftwareRenderer=true;this.cache=new WeakMap();this.colors=new Map();this.static=[];this.dynamic=[];this.prepared=false;this.lastRender=0;}
 setPixelRatio(){}setSize(w,h){const r=Math.min(1,850/w);this.domElement.width=Math.round(w*r);this.domElement.height=Math.round(h*r);}
 setAnimationLoop(fn){this.loop=fn;const next=()=>{if(this.loop){this.loop();requestAnimationFrame(next);}};requestAnimationFrame(next);}
 triangles(geo){if(this.cache.has(geo))return this.cache.get(geo);const p=geo.attributes.position,uv=geo.attributes.uv,index=geo.index,tri=[];for(let k=0;k<(index?index.count:p.count);k+=3){const ids=[0,1,2].map(i=>index?index.getX(k+i):k+i);tri.push({p:ids.map(i=>[p.getX(i),p.getY(i),p.getZ(i)]),uv:uv?ids.map(i=>[uv.getX(i),uv.getY(i)]):null});}this.cache.set(geo,tri);return tri;}
 face(tri,m,material,object){const e=m.elements,p=tri.p.map(v=>[e[0]*v[0]+e[4]*v[1]+e[8]*v[2]+e[12],e[1]*v[0]+e[5]*v[1]+e[9]*v[2]+e[13],e[2]*v[0]+e[6]*v[1]+e[10]*v[2]+e[14]]),a=p[0],b=p[1],c=p[2],ux=b[0]-a[0],uy=b[1]-a[1],uz=b[2]-a[2],vx=c[0]-a[0],vy=c[1]-a[1],vz=c[2]-a[2],nx=uy*vz-uz*vy,ny=uz*vx-ux*vz,nz=ux*vy-uy*vx,l=Math.hypot(nx,ny,nz)||1,n=[nx/l,ny/l,nz/l],key=material.id+':'+n.map(x=>Math.round(x*10)).join(',');let color=this.colors.get(key);if(!color){const base=material.color.clone().convertLinearToSRGB(),shade=material.isMeshBasicMaterial?1:.48+.52*Math.max(0,n[0]*-.5+n[1]*.75+n[2]*.4);color=`rgb(${Math.min(255,Math.round(base.r*255*shade))},${Math.min(255,Math.round(base.g*255*shade))},${Math.min(255,Math.round(base.b*255*shade))})`;this.colors.set(key,color);}return {p,n,material,object,uv:tri.uv,color,c:[(a[0]+b[0]+c[0])/3,(a[1]+b[1]+c[1])/3,(a[2]+b[2]+c[2])/3],ground:a[1]<.25&&b[1]<.25&&c[1]<.25};}
 prepare(scene){scene.updateMatrixWorld(true);const tmp=new T.Matrix4(),mat=new T.Matrix4();scene.traverse(o=>{if(!o.isMesh||!o.geometry||!o.visible)return;const material=Array.isArray(o.material)?o.material[0]:o.material;if(o.isInstancedMesh){for(let i=0;i<o.count;i++){o.getMatrixAt(i,tmp);mat.multiplyMatrices(o.matrixWorld,tmp);for(const tri of this.triangles(o.geometry))this.static.push(this.face(tri,mat,material,o));}}else if(o.parent===scene){for(const tri of this.triangles(o.geometry))this.static.push(this.face(tri,o.matrixWorld,material,o));}else this.dynamic.push(o);});this.prepared=true;}
 render(scene,camera){const now=performance.now();if(now-this.lastRender<38)return;this.lastRender=now;if(!this.prepared)this.prepare(scene);scene.updateMatrixWorld(true);camera.updateMatrixWorld(true);const ctx=this.ctx,W=this.domElement.width,H=this.domElement.height,e=camera.matrixWorldInverse.elements,C=camera.position,F=H/(2*Math.tan(camera.fov*Math.PI/360)),faces=[];ctx.fillStyle='#d5c3a3';ctx.fillRect(0,0,W,H);
 const project=f=>{if(!f.object.visible||f.material.opacity<.03)return;const a=f.p[0],n=f.n,dx=C.x-f.c[0],dy=C.y-f.c[1],dz=C.z-f.c[2],dist=dx*dx+dy*dy+dz*dz;if(dist>10000||f.material.side!==T.DoubleSide&&(C.x-a[0])*n[0]+(C.y-a[1])*n[1]+(C.z-a[2])*n[2]<=0)return;let v=f.p.map(p=>[e[0]*p[0]+e[4]*p[1]+e[8]*p[2]+e[12],e[1]*p[0]+e[5]*p[1]+e[9]*p[2]+e[13],e[2]*p[0]+e[6]*p[1]+e[10]*p[2]+e[14]]);if(v.every(p=>p[2]>-.25))return;const original=v.every(p=>p[2]<=-.25);if(!original){const out=[];for(let i=0;i<v.length;i++){const a=v[i],b=v[(i+1)%v.length],ai=a[2]<=-.25,bi=b[2]<=-.25;if(ai)out.push(a);if(ai!==bi){const r=(-.25-a[2])/(b[2]-a[2]);out.push([a[0]+(b[0]-a[0])*r,a[1]+(b[1]-a[1])*r,-.25]);}}v=out;}if(v.length<3)return;const p=v.map(q=>[W/2+q[0]/-q[2]*F,H/2-q[1]/-q[2]*F]);if(p.every(q=>q[0]<0)||p.every(q=>q[0]>W)||p.every(q=>q[1]<0)||p.every(q=>q[1]>H))return;faces.push({f,p,z:v.reduce((s,q)=>s-q[2],0)/v.length,fog:Math.max(0,Math.min(.7,(Math.sqrt(dist)-55)/70)),textured:original&&f.material.map?.repeat?.x===1});};
 for(const f of this.static)project(f);for(const o of this.dynamic){if(!o.parent.visible)continue;const mat=Array.isArray(o.material)?o.material[0]:o.material;for(const tri of this.triangles(o.geometry))project(this.face(tri,o.matrixWorld,mat,o));}faces.sort((a,b)=>a.f.ground!==b.f.ground?(a.f.ground?-1:1):a.f.ground&&Math.abs(a.f.c[1]-b.f.c[1])>.008?a.f.c[1]-b.f.c[1]:b.z-a.z);for(const face of faces){const {f,p}=face;ctx.globalAlpha=f.material.opacity??1;ctx.beginPath();p.forEach((q,i)=>i?ctx.lineTo(q[0],q[1]):ctx.moveTo(q[0],q[1]));ctx.closePath();ctx.fillStyle=f.color;ctx.fill();if(face.textured&&f.uv&&p.length===3){const image=f.material.map.source.data,u=f.uv.map(q=>[q[0]*image.width,(1-q[1])*image.height]),den=u[0][0]*(u[1][1]-u[2][1])+u[1][0]*(u[2][1]-u[0][1])+u[2][0]*(u[0][1]-u[1][1]);if(Math.abs(den)>.001){const calc=j=>[(p[0][j]*(u[1][1]-u[2][1])+p[1][j]*(u[2][1]-u[0][1])+p[2][j]*(u[0][1]-u[1][1]))/den,(p[0][j]*(u[2][0]-u[1][0])+p[1][j]*(u[0][0]-u[2][0])+p[2][j]*(u[1][0]-u[0][0]))/den,(p[0][j]*(u[1][0]*u[2][1]-u[2][0]*u[1][1])+p[1][j]*(u[2][0]*u[0][1]-u[0][0]*u[2][1])+p[2][j]*(u[0][0]*u[1][1]-u[1][0]*u[0][1]))/den];const x=calc(0),y=calc(1);ctx.save();ctx.clip();ctx.transform(x[0],y[0],x[1],y[1],x[2],y[2]);ctx.drawImage(image,0,0);ctx.restore();}}if(face.fog){ctx.globalAlpha=face.fog;ctx.fillStyle='#d8bd9a';ctx.fill();}}ctx.globalAlpha=1;this.info.render.calls=faces.length;}
}
